def transform(g,dr,dc):
 R,C=len(g),len(g[0]); wall=2; seen=set(); objs=[]
 for r in range(R):
  for c in range(C):
   v=g[r][c]
   if v in (0,wall) or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     p=x+dx,y+dy
     if 0<=p[0]<R and 0<=p[1]<C and p not in seen and g[p[0]][p[1]]==v: seen.add(p); q.append(p)
   objs.append({'v':v,'cells':cells})
 # process nearest to wall first, i.e. topmost for up / leftmost for left
 objs.sort(key=lambda o: min(r*dr+c*dc for r,c in o['cells']))
 settled=set(); out=[[wall if x==wall else 0 for x in row] for row in g]
 for o in objs:
  cells=o['cells'][:]
  while True:
   sh=[(r+dr,c+dc) for r,c in cells]
   if any(r<0 or c<0 or r>=R or c>=C or g[r][c]==wall or (r,c) in settled for r,c in sh): break
   cells=sh
  for r,c in cells: out[r][c]=o['v']; settled.add((r,c))
 return out
